<?php
declare(strict_types=1);
require_once __DIR__.'/PortalActionAcceptanceFixture.php';
use DigiForge\Database\Tables;
use DigiForge\Orders\ReplacementReviewRepository;
final class ReplacementSupportAcceptanceTest extends WP_UnitTestCase {
 protected function setUp():void {parent::setUp();DigiForge\Core\Activator::activate();DigiForge\Core\Settings::protectProduction();wp_set_current_user(self::factory()->user->create(['role'=>'administrator']));}
 private function order(string $shop):int {
  $order=(new DigiForge\Orders\Repository())->createOrder(['shop_reference'=>$shop,'channel'=>'etsy','environment'=>'sandbox']);self::assertNotWPError($order);global $wpdb;$now=current_time('mysql',true);self::assertSame(1,$wpdb->update(Tables::orders(),['state'=>'CLOSED','approved_by'=>get_current_user_id(),'approved_at'=>$now],['id'=>$order['id']]));self::assertSame(1,$wpdb->insert(Tables::order_line_items(),['order_id'=>$order['id'],'product_version_id'=>99,'listing_id'=>88,'provider_mapping_id'=>77,'quantity'=>1,'currency'=>'USD','validation_status'=>'VALIDATED','created_at'=>$now,'updated_at'=>$now]));return (int)$order['id'];
 }
 public function testClosedOrderNativeRequestAndHumanReviewAreImmutableWithoutExecutionAuthority():void {
  $id=$this->order('personalized_pod');$repo=new ReplacementReviewRepository();PortalActionAcceptanceFixture::invoke('REPLACEMENT_REQUEST_ACTION',['order_id'=>$id,'shop_key'=>'personalized_pod','request_key'=>'replacement-key']);$case=$repo->request($id,'personalized_pod','replacement-key');self::assertNotWPError($case);self::assertTrue($case['idempotent_replay']);self::assertFalse($case['external_execution_authorized']);$rows=$repo->snapshot('personalized_pod')['items'];self::assertContains($case['case_id'],array_column($rows,'case_id'));
  PortalActionAcceptanceFixture::invoke('REPLACEMENT_DECISION_ACTION',['case_id'=>$case['case_id'],'shop_key'=>'personalized_pod','decision'=>'APPROVED_LOCAL_REVIEW']);$review=$repo->decide($case['case_id'],'personalized_pod','APPROVED_LOCAL_REVIEW');self::assertNotWPError($review);self::assertTrue($review['idempotent_replay']);self::assertFalse($review['external_execution_authorized']);self::assertWPError($repo->decide($case['case_id'],'personalized_pod','REJECTED_LOCAL_REVIEW'));
  global $wpdb;self::assertSame('CLOSED',$wpdb->get_var($wpdb->prepare('SELECT state FROM '.Tables::orders().' WHERE id=%d',$id)));self::assertSame('2',$wpdb->get_var($wpdb->prepare('SELECT COUNT(*) FROM '.Tables::audit_log().' WHERE object_type=%s AND object_id=%s AND event_type IN (%s,%s)','order',(string)$id,ReplacementReviewRepository::REQUESTED,ReplacementReviewRepository::DECIDED)));self::assertTrue(DigiForge\Core\Settings::get('stop_all',true));self::assertTrue(DigiForge\Core\Settings::safety_locked());
 }
 public function testChangedSourceAndCrossShopCannotApproveOrReplaySupportCase():void {
  $id=$this->order('personalized_pod');$repo=new ReplacementReviewRepository();$case=$repo->request($id,'personalized_pod','source-key');self::assertNotWPError($case);self::assertWPError($repo->request($id,'standard_pod','cross'));self::assertWPError($repo->decide($case['case_id'],'standard_pod','APPROVED_LOCAL_REVIEW'));self::assertNotContains($case['case_id'],array_column($repo->snapshot('standard_pod')['items'],'case_id'));global $wpdb;self::assertSame(1,$wpdb->update(Tables::order_line_items(),['provider_mapping_id'=>78],['order_id'=>$id]));self::assertSame('replacement_review_stale',$repo->decide($case['case_id'],'personalized_pod','APPROVED_LOCAL_REVIEW')->get_error_code());self::assertSame('replacement_review_replay_conflict',$repo->request($id,'personalized_pod','source-key')->get_error_code());$rows=$repo->snapshot('personalized_pod')['items'];$matching=array_values(array_filter($rows,static fn(array $r):bool=>$r['case_id']===$case['case_id']));self::assertSame('SOURCE_CHANGED',$matching[0]['state']);
 }
 public function testUnavailableAuditAndUnauthorizedOperatorsDoNotClaimSupportSuccess():void {
  $id=$this->order('digital');global $wpdb;$table=Tables::audit_log();$fail=static fn(string $sql):string=>str_contains($sql,'FROM '.$table)&&str_contains($sql,ReplacementReviewRepository::REQUESTED)?'SELECT * FROM no_such_support_evidence_table':$sql;add_filter('query',$fail);try{self::assertWPError((new ReplacementReviewRepository())->request($id,'digital','unavailable'));self::assertSame('UNAVAILABLE',(new ReplacementReviewRepository())->snapshot('digital')['query_state']);}finally{remove_filter('query',$fail);}
  wp_set_current_user(self::factory()->user->create(['role'=>'subscriber']));self::assertWPError((new ReplacementReviewRepository())->request($id,'digital','denied'));self::assertSame('ACCESS_DENIED',(new ReplacementReviewRepository())->snapshot('digital')['query_state']);
 }
}
